LET $rows = QUERY SELECT {{columns:main}} FROM {{t:main}} WHERE {{where:main}} ORDER BY {{orderBy:main}} LIMIT {{limit}} OFFSET {{offset}};
LET $total = QUERY SELECT COUNT(*) AS total FROM {{t:main}} WHERE {{where:main}};
RETURN 200 { "rows": $rows.rows, "total": $total.rows[0].total };

LET $row = QUERY SELECT {{allColumns:main}} FROM {{t:main}} WHERE {{idColumn:main}} = {{id}} LIMIT 1;
IF LEN($row.rows) == 0
  RETURN 404 { "ok": false, "error": "NOT_FOUND" };
END
RETURN 200 { "row": $row.rows[0] };

LET $rows = QUERY SELECT {{columns:main}} FROM {{t:main}} WHERE {{where:main}} ORDER BY {{orderBy:main}} LIMIT {{limit}} OFFSET {{offset}};
LET $total = QUERY SELECT COUNT(*) AS total FROM {{t:main}} WHERE {{where:main}};
RETURN 200 { "rows": $rows.rows, "total": $total.rows[0].total };

LET $row = QUERY SELECT {{allColumns:main}} FROM {{t:main}} WHERE {{idColumn:main}} = {{id}} LIMIT 1;
IF LEN($row.rows) == 0
  RETURN 404 { "ok": false, "error": "NOT_FOUND" };
END
LET $replies = QUERY SELECT {{columns:reply}} FROM {{t:reply}} WHERE ticket_id = {{id}} ORDER BY created_at ASC;
RETURN 200 { "row": $row.rows[0], "replies": $replies.rows };

LET $t = QUERY SELECT id, status FROM {{t:main}} WHERE {{idColumn:main}} = {{id}} LIMIT 1;
IF LEN($t.rows) == 0
  RETURN 404 { "ok": false, "error": "NO_TICKET" };
END
EXEC UPDATE {{t:main}} SET assignee = {{body.assignee}}, status = 1 WHERE {{idColumn:main}} = {{id}};
RETURN 200 { "ok": true };

EXEC INSERT INTO {{t:reply}} (ticket_id, author, content) VALUES ({{id}}, {{body.author}}, {{body.content}});
EXEC UPDATE {{t:main}} SET updated_at = NOW() WHERE {{idColumn:main}} = {{id}};
RETURN 201 { "ok": true };

